import { chromium } from '@playwright/test'
import fs from 'fs'
const b = await chromium.launch({ executablePath: process.env.PLAYWRIGHT_CHROMIUM_EXECUTABLE, headless: true })
const ctx = await b.newContext({ viewport: { width: 390, height: 844 } })
const p = await ctx.newPage()
await p.goto('http://127.0.0.1:8095/#/pages/inspection/index?kind=post', { waitUntil: 'domcontentloaded' })
await p.waitForSelector('.ui-ref8443 .form-page')
await p.evaluate(async () => {
  try {
    await document.fonts.load('700 14px "Noto Sans SC:Medium"')
    await document.fonts.load('400 14px "Noto Sans SC:Regular"')
    await document.fonts.load('500 16px "Noto Sans SC:Medium"')
  } catch (e) {}
  await document.fonts.ready
})
await p.waitForTimeout(1200)
const cdp = await ctx.newCDPSession(p)
const { data } = await cdp.send('Page.captureScreenshot', { format: 'png' })
fs.writeFileSync('artifacts/post-final.png', Buffer.from(data, 'base64'))
console.log('ok')
await b.close()

