await p.goto('http://127.0.0.1:8095/#/pages/inspection/index?kind=post', { waitUntil: 'domcontentloaded' })
await p.waitForSelector('.ui-ref8443 .form-page')
for (let i = 0; i < 8; i++) {
  await p.waitForTimeout(1500)
  const st = await p.evaluate(() => [...document.fonts].filter(f => f.family.includes('SC') || f.family.includes('Jakarta')).map(f => f.family + '/' + f.weight + '/' + f.status))
  console.log('t=' + (i + 1) * 1.5 + 's', JSON.stringify(st))
}
const w = await p.evaluate(() => { const cb = document.querySelector('.choice-b'); return cb ? getComputedStyle(cb).fontWeight : null })
console.log('final choice-b fontWeight', w)
await b.close()

