    const rect = h2.getBoundingClientRect()
    return { ff: cs.fontFamily, fw: cs.fontWeight, fs: cs.fontSize, h: Math.round(rect.height), w: Math.round(rect.width), text: h2.textContent.trim() }
  })
  await p.close()
  return r
}
