import { chromium } from '@playwright/test'
const b = await chromium.launch({ executablePath: process.env.PLAYWRIGHT_CHROMIUM_EXECUTABLE, headless: true })
async function grab(url, prep) {
  const p = await (await b.newContext({ viewport: { width: 390, height: 844 } })).newPage()
  await p.goto(url, { waitUntil: 'domcontentloaded' })
  if (prep) await prep(p)
  await p.waitForTimeout(2500)
  const r = await p.evaluate(() => {
    const cb = document.querySelector('.choice-b, .choice-label b')
    const h2 = document.querySelector('.summary h2')
    const g = e => e ? { ff: getComputedStyle(e).fontFamily, fw: getComputedStyle(e).fontWeight, fs: getComputedStyle(e).fontSize } : null
    return { choice: g(cb), h2: g(h2) }
  })
  await p.close()
  return r
}
const ref = await grab('http://localhost:8443/', async p => { await p.waitForTimeout(400); await p.getByRole('button', { name: '汛后检查' }).click(); await p.getByRole('button', { name: '继续填报' }).first().click(); await p.waitForSelector('.form-page') })
const mine = await grab('http://127.0.0.1:8095/#/pages/inspection/index?kind=post')
console.log('REF ', JSON.stringify(ref))
console.log('MINE', JSON.stringify(mine))
await b.close()
